{
  "title": "Verify demo.html loads and resizes",
  "timeout_ms": 90000,
  "code": "const { chromium } = await import('playwright');
var browser = await chromium.launch();
var page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
const errors = [];
page.on('pageerror', e => errors.push('pageerror: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('console.error: ' + m.text()); });
await page.addInitScript(() => {
  const RealRO = window.ResizeObserver;
  window.__ro = { instances: [], disconnected: 0, observed: [] };
  window.ResizeObserver = class extends RealRO {
    constructor(cb) { super(cb); this.id = window.__ro.instances.length; window.__ro.instances.push(this); }
    observe(el) { window.__ro.observed.push(el); return super.observe(el); }
    disconnect() { window.__ro.disconnected++; return super.disconnect(); }
  };
});
await page.goto('file:///D:/dev/ab-tasks/chessground-dsv4-r1/demo.html');
await page.waitForSelector('cg-board');
await page.waitForTimeout(300);
const before = await page.evaluate(() => ({
  boards: document.querySelectorAll('cg-board').length,
  squares: document.querySelectorAll('cg-board square').length,
  pieces: document.querySelectorAll('cg-board piece').length,
  roCount: window.__ro.instances.length,
  roObserved: window.__ro.observed.length,
  cgWrap: document.querySelectorAll('.cg-wrap').length,
}));
// Resize board-1 to force the ResizeObserver to fire
await page.evaluate(() => {
  const b = document.getElementById('board-1');
  b.style.width = '260px'; b.style.height = '260px';
});
await page.waitForTimeout(400);
// Resize the viewport too
await page.setViewportSize({ width: 900, height: 700 });
await page.waitForTimeout(400);
const after = await page.evaluate(() => ({
  boards: document.querySelectorAll('cg-board').length,
  squares: document.querySelectorAll('cg-board square').length,
  pieces: document.querySelectorAll('cg-board piece').length,
  roCount: window.__ro.instances.length,
  roDisconnected: window.__ro.disconnected,
}));
const shots = {};
shots.resized = await page.screenshot({ fullPage: true });
await browser.close();
nodeRepl.write('BEFORE ' + JSON.stringify(before) + '\nAFTER ' + JSON.stringify(after) + '\nERRORS ' + JSON.stringify(errors));
await nodeRepl.emitImage(shots.resized);"
}

